SELECT mi1.info, n.name, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_356
WHERE (it1.id IN ('2','3','5')) AND (n.name ILIKE '%deb%') AND (kt.kind IN ('tv series','video movie')) AND it2.id = pi.info_type_id AND it1.id = non_leaf_356.mi1_info_type_id AND (it2.id IN ('37')) AND kt.id = non_leaf_356.t_kind_id AND n.id = non_leaf_356.ci_person_id AND (t.production_year >= 1925) AND (rt.role IN ('actress','cinematographer','composer','costume designer')) AND n.id = pi.person_id AND (mi1.info IN ('Action','Adult','Adventure','Animation','Black AND White','Color','Comedy','Documentary','Drama','Family','Fantasy','Horror','Music','Reality-TV','Romance','Sci-Fi','Short','Thriller','USA:R','USA:X'));